      "kind": "api_contract.json",
      "language": "json",
      "source": "{\"resources\":{\"Task\":{\"attributes\":{\"id\":\"string (uuid)\",\"title\":\"string\",\"description\":\"string\",\"status\":\"enum: pending, in_progress, completed\"}}},\"endpoints\":[{\"method\":\"GET\",\"path\":\"/tasks\",\"description\":\"Retrieve all tasks\",\"response\":{\"status\":200,\"body\":\"Task[]\"}},{\"method\":\"POST\",\"path\":\"/tasks\",\"description\":\"Create a new task\",\"request\":{\"body\":{\"title\":\"string (required)\",\"description\":\"string (optional)\",\"status\":\"enum (optional, default: pending)\"}},\"response\":{\"status\":201,\"body\":\"Task\"}},{\"method\":\"GET\",\"path\":\"/tasks/{id}\",\"description\":\"Retrieve a specific task\",\"response\":{\"status\":200,\"body\":\"Task\"}},{\"method\":\"PUT\",\"path\":\"/tasks/{id}\",\"description\":\"Update a specific task\",\"request\":{\"body\":{\"title\":\"string (optional)\",\"description\":\"string (optional)\",\"status\":\"enum (optional)\"}},\"response\":{\"status\":200,\"body\":\"Task\"}},{\"method\":\"DELETE\",\"path\":\"/tasks/{id}\",\"description\":\"Delete a specific task\",\"response\":{\"status\":204,\"body\":null}}]}"
    }
